#!/bin/bash
# tab.sh <census-dir>: one line per seam
for f in $1/*.txt; do grep -a '^ROW' $f | node -e 'const l=require("fs").readFileSync(0,"utf8");if(!l.trim()){process.exit()};const r=JSON.parse(l.slice(4));let w="";if(!r.ok){const m=r.msg;w=/anytime deadline/.test(m)?"DEADLINE ("+r.passes+")":/no pacing is clean/.test(m)?"hold: MOVING_WAIT no clean pacing":/combat ladder is EXHAUSTED/.test(m)?"walk: ladder EXHAUSTED on "+(m.match(/bomb:bombpusher@112,128#\d+|spinner:spinner@\d+,\d+|chaser:[a-z]+@\d+,\d+/)||["?"])[0]:/died at t\d+ \(bomb/.test(m)?"press kill: player died "+m.match(/died at t\d+ \([^)]*\)/)[0]:/There is no step out/.test(m)?"press kill: no step out":m.slice(0,100)}const k=r.bpw?`kept ${r.bpw.kept.length} ref ${r.bpw.refused.length}`:"";console.log([r.seam,r.seam%45,r.ok?"SOLVED":"REFUSED",r.work,r.ticks??"-",(r.hits||[]).length,w,k].join("\t"))'; done
